    if hasattr(client, 'Moderation'):
        result = client.Moderation.create(input=text)
        return {'provider': 'assemblyai', 'result': result}
    return {'provider': 'assemblyai', 'result': {'flagged': False, 'categories': {}, 'text': text}}


